import {IncomingMessage} from 'http';
import {Duplex} from 'stream';
import {v4 as uuidv4} from 'uuid';
import type {WsAuthenticator} from '../../types/auth.js';
import type {SessionStore} from '../../types/sessionStore.js';
import type {ConnectedMessage} from '../../types/messages.js';
import type {AuthenticatedUser, ChatSession} from '../../types/session.js';
import {ErrorCodes} from '../../types/session.js';
import {sendError} from './sender.js';
import {isValidWsPath, rejectSocket, parseWsData, sessionIdFromUpgrade, newSessionRequested} from './helpers.js';
import {credentialFromSubprotocol} from './subprotocol.js';
import {replayEntries, resumableSession, resumeFields} from './sessionResume.js';
import type {ConnectInfo, SessionResumeOptions} from './sessionResume.js';
import {log} from '../../shared/logger.js';

export interface ExtWebSocket extends WebSocket {
  isAlive: boolean;
  userId: string | number;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
  requestedSessionId?: string;
  startNewSession?: boolean;
}

export interface ConnectionHandlerDeps {
  wsAuth: WsAuthenticator;
  sessionStore: SessionStore;
  /** `signal` is the connection's own, aborted when its socket closes (specs/hal-engine-abandon-on-close/spec.md). */
  handleMessage: (
    ws: WebSocket,
    session: import('../../types/session.js').ChatSession,
    rawMessage: unknown,
    signal?: AbortSignal
  ) => Promise<void>;
  basePath: string;
  onConnect?: (session: import('../../types/session.js').ChatSession, connection: ConnectInfo) => void | Promise<void>;
  onDisconnect?: (sessionId: string) => void | Promise<void>;
  resume?: SessionResumeOptions;
}
export function createUpgradeHandler(wss: WebSocketServer, deps: ConnectionHandlerDeps) {
  return function handleUpgrade(request: IncomingMessage, socket: Duplex, head: Buffer): void {
    // Nothing may throw out of this listener: the `upgrade` event has no catch above it, so a throw ends the process.
    if (!request.headers.host || !isValidWsPath(request.url || '', deps.basePath)) {
      rejectSocket(socket, '400 Bad Request');
      return;
    }

    authenticate(deps.wsAuth, request)
      .then(user => {
        if (!user) {
          rejectSocket(socket, '401 Unauthorized');
          return;
        }

        wss.handleUpgrade(request, socket, head, ws => {
          const extWs = ws as ExtWebSocket;
          extWs.userId = user.id;
          extWs.workspaceId = user['workspaceId'] as string | number | undefined;
          extWs.authHeaders = {
            cookie: request.headers.cookie,
            authorization: request.headers.authorization || bearerFromWebSocketProtocol(request),
            host: (request.headers['x-forwarded-host'] as string | undefined) ?? request.headers.host,
          };
          extWs.isAlive = true;
          if (deps.resume?.enabled) {
            extWs.requestedSessionId = sessionIdFromUpgrade(request.url || '', deps.basePath);
            extWs.startNewSession = newSessionRequested(request.url || '', deps.basePath);
          }
          wss.emit('connection', extWs, request);
        });
      })
      .catch((error: unknown) => {
        // The type alone: an authenticator's message can carry the credential it was checking.
        log.error('ws', 'authenticator failed', {errorType: error instanceof Error ? error.name : typeof error});
        rejectSocket(socket, '500 Internal Server Error');
      });
  };
}

// Async, so a synchronous throw becomes a rejection (answered 500) and a user returned without a promise still resolves.
async function authenticate(wsAuth: WsAuthenticator, request: IncomingMessage): Promise<AuthenticatedUser | null> {
  return wsAuth(request);
}

function bearerFromWebSocketProtocol(req: IncomingMessage): string | undefined {
  const token = credentialFromSubprotocol(req.headers['sec-websocket-protocol']);
  return token ? `Bearer ${token}` : undefined;
}

export function createConnectionHandler(deps: ConnectionHandlerDeps, examplePrompts: string[]) {
  return function handleConnection(ws: ExtWebSocket): void {
    // The listener stays synchronous: an async one rejects into the emitter, and node ends the process on that.
    openSession(deps, examplePrompts, ws).catch((error: unknown) => {
      log.error('ws', 'connection setup failed', {error: messageOf(error)});
      // Resumed before closing: a paused socket never reads the close frame it would be waiting for.
      ws.resume();
      ws.close(1011, 'Connection setup failed');
    });
  };
}

// The sockets open on each session, oldest first: a resumed session can be open on more than one at once.
const openSockets = new WeakMap<ChatSession, ExtWebSocket[]>();

async function openSession(deps: ConnectionHandlerDeps, examplePrompts: string[], ws: ExtWebSocket): Promise<void> {
  // A requested id is never adopted for a new session: that would be session fixation.
  let sessionId = uuidv4();
  const state = {closed: false, settled: false, notified: false, delivered: false};
  const held: {session?: ChatSession; socket: ExtWebSocket} = {socket: ws};
  // One per connection, not per message or session: a close abandons the turn in flight and every message queued behind it.
  const connection = new AbortController();

  ws.on('error', (error: Error) => {
    log.error('ws', 'connection error', {sessionId, error: error.message});
  });

  ws.on('pong', () => {
    ws.isAlive = true;
  });

  ws.on('close', () => {
    // First, so the turn stops before the session is torn down and before onDisconnect.
    connection.abort();
    state.closed = true;
    log.info('ws', 'disconnected', {sessionId});
    if (state.settled) endSession(deps, sessionId, state, held);
  });

  // Paused across the await so a frame arriving before the message listener exists is buffered, not dropped.
  ws.pause();

  const outcome = await resumableSession(deps.sessionStore, ws, deps.resume);
  const resumed = outcome.session;
  if (resumed) sessionId = resumed.sessionId;
  const session = resumed ?? (await createSession(deps, sessionId, ws));
  state.settled = true;

  if (session === undefined) {
    // Resumed before closing: ws.close() on a paused socket waits for a close frame it can never read.
    ws.resume();
    ws.close(1011, 'Session store unavailable');
    return;
  }

  // A new session is this socket's from the start; a resumed one only once this socket is known to be open.
  if (!resumed) join(session, ws);

  if (state.closed) {
    // Held first: a store that implements no evict still holds this session, and it carries the caller's credentials.
    held.session = session;
    await evictUnlessResumed(deps, sessionId, resumed);
    endSession(deps, sessionId, state, held);
    ws.resume();
    return;
  }

  if (resumed) join(resumed, ws);
  held.session = session;

  log.info('ws', 'connected', {sessionId, userId: ws.userId});

  const connected: ConnectedMessage = {
    type: 'connected',
    sessionId,
    message: 'Connected to HAL Engine',
    examplePrompts,
    ...resumeFields(deps.resume, outcome),
  };
  // A socket that died between the check above and this frame must not leave the session it was created for behind.
  try {
    ws.send(JSON.stringify(connected));
    if (resumed) replayEntries(ws, resumed);
  } catch (error) {
    log.error('ws', 'connected frame failed', {sessionId, error: messageOf(error)});
    await evictUnlessResumed(deps, sessionId, resumed);
    endSession(deps, sessionId, state, held);
    ws.resume();
    ws.close(1011, 'Connection setup failed');
    return;
  }

  state.delivered = true;

  // Deferred, not inline: a synchronous throw in the `connection` listener corrupts an already-upgraded socket.

  // A microtask, not setImmediate: it drains before the loop delivers any inbound frame on this socket.
  queueMicrotask(() =>
    runHook('onConnect', sessionId, () => deps.onConnect?.(session, {resumed: resumed !== undefined}))
  );

  ws.on('message', (frame: Buffer | string) => {
    const parsed = parseWsData(frame);
    if (parsed === null) {
      sendError(ws, ErrorCodes.INVALID_FORMAT, 'Invalid JSON');
      return;
    }
    log.info('ws', 'message received', {sessionId, type: (parsed as Record<string, unknown>).type as string});
    deps.handleMessage(ws, session, parsed, connection.signal);
  });

  ws.resume();
}

// Joined as the newest socket on the session, which carries this upgrade's credentials from here on.
function join(session: ChatSession, ws: ExtWebSocket): void {
  openSockets.set(session, [...(openSockets.get(session) ?? []), ws]);
  session.authHeaders = ws.authHeaders;
}

// `undefined` rather than a throw: one store failure closes one socket instead of ending the process.
async function createSession(
  deps: ConnectionHandlerDeps,
  sessionId: string,
  ws: ExtWebSocket
): Promise<ChatSession | undefined> {

import type {ChatSession} from './session.js';

/** A value a store may return directly or resolve to, so a database-backed member needs no new interface. */
export type Awaitable<T> = T | Promise<T>;

export interface BaseSession {
  sessionId: string;
  userId: string | number;
}

/** What a store knows of a session id. `expired` carries the owner's id, so ownership can be checked, and never the conversation. */
export type SessionLookup<T extends BaseSession = ChatSession> =
  {status: 'active'; session: T} | {status: 'expired'; userId: string | number} | {status: 'missing'};

/** What a conversation list needs of one session: never its entries, and never its credentials. */
export interface SessionSummary {
  sessionId: string;
  createdAt: Date;
  updatedAt: Date;
  entryCount: number;
}

/** Where a page of conversations resumes from: the last row the caller saw, which a `SessionSummary` satisfies. */
export interface SessionCursor {
  /** A `Date`, an ISO string or an epoch number, so a row that went through JSON still pages (specs/hal-engine-conversation-list/spec.md). */
  updatedAt: Date | string | number;
  sessionId: string;
}

/** A window onto a user's conversations, newest activity first; `before` pages down that same order. */
export interface SessionListOptions {
  limit?: number;
  before?: SessionCursor;
}

export interface SessionCreateOptions {
  authHeaders?: ChatSession['authHeaders'];
  workspaceId?: string | number;
}

export interface SessionStore<T extends BaseSession = ChatSession> {
  create(sessionId: string, userId: string | number, options?: SessionCreateOptions): Awaitable<T>;
  get(sessionId: string): Awaitable<T | undefined>;
  delete(sessionId: string): Awaitable<boolean>;
  count(): Awaitable<number>;
  clear(): Awaitable<void>;
  /** Drops a session the client never received, without erasing anything a consumer would want kept. */
  evict?(sessionId: string): Awaitable<boolean>;
  /** Write signal: fires once per processed user message; failures are swallowed (specs/hal-engine-session-write-signal/spec.md). */
  save?(session: T): Awaitable<void>;
  /** Summaries of the user's conversations, newest activity first, so a client can offer a list of them (specs/hal-engine-conversation-list/spec.md). */
  listFor?(userId: string | number, options?: SessionListOptions): Awaitable<SessionSummary[]>;
  /** The user's most recently active session the store still holds, so a connect that names none can continue it (specs/hal-engine-session-resume/spec.md). */
  latestFor?(userId: string | number): Awaitable<T | undefined>;
  /** Tells an expired session from a missing one; `missing` is always a permitted answer, and a store without it behaves as `get` (specs/hal-engine-session-resume/spec.md). */
  lookup?(sessionId: string): Awaitable<SessionLookup<T>>;
}

import type {AddressInfo} from 'node:net';
import {WebSocket} from 'ws';
import type {Express} from 'express';
import {createServer} from './createServer.js';
import type {HalServer, HalServerOptions} from './createServer.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';
import type {MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import type {SessionStore} from '../types/sessionStore.js';

// Shared by the suites that need a real upgrade over a real socket, which no double can stand in for.

const servers: Array<{stop: () => Promise<void>}> = [];
const clients: WebSocket[] = [];

/** An orchestrator that answers once and stops, which is what commits the turn's assistant entry. */
export const answeringOrchestrator: ChatOrchestrator = {
  processMessage: async () => 'hi',
  async *processMessageStream(): AsyncGenerator<MessageChunk> {
    yield {type: 'text', text: 'hi'};
    yield {type: 'stop', stopReason: 'end_turn'};
  },
};

/** Starts an engine on an ephemeral port and returns the URL a client should open. */
export async function startEngine(
  sessionStore: SessionStore,
  onDisconnect?: (sessionId: string) => void
): Promise<string> {
  const {url} = await startEngineWith({sessionStore, onDisconnect});
  return url;
}

/** Starts an engine with whatever a suite overrides, returning the server itself beside the URL a client should open. */
export async function startEngineWith(
  options: Partial<HalServerOptions> & Pick<HalServerOptions, 'sessionStore'>
): Promise<{url: string; hal: HalServer}> {
  const hal = createServer({
    app: (() => undefined) as unknown as Express,
    wsAuth: async () => ({id: 'u1'}),
    orchestrator: answeringOrchestrator,
    ...options,
  });
  await hal.start(0);
  servers.push(hal);
  const {port} = hal.server.address() as AddressInfo;
  return {url: `ws://127.0.0.1:${port}/hal/ws/c1`, hal};
}

/** Opens a client that the suite's teardown will close, whether its test passed or failed. */
export function connectClient(url: string, token = 't'): WebSocket {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, token]);
  clients.push(client);
  return client;
}

/** A promise a test settles by hand, to hold a stream or a hook at a point of its choosing. */
export function deferred(): {until: Promise<void>; release: () => void} {
  let release = (): void => undefined;
  const until = new Promise<void>(resolve => {
    release = resolve;
  });
  return {until, release};
}

/** Resolves with every frame type seen up to and including the first `until` frame. */
export function framesUntil(client: WebSocket, until: string): Promise<string[]> {
  const seen: string[] = [];
  return new Promise<string[]>(resolve => {
    client.on('message', raw => {
      const {type} = JSON.parse(String(raw)) as {type: string};
      seen.push(type);
      if (type === until) resolve(seen);
    });
  });
}

/** Opens a client that asks one question the moment the socket opens, resolving on the first `until` frame. */
export function askOnOpen(
  url: string,
  {until = 'stream_end', token}: {until?: string; token?: string} = {}
): {client: WebSocket; finished: Promise<string[]>} {
  const client = connectClient(url, token);
  const finished = framesUntil(client, until);
  client.on('open', () => client.send(JSON.stringify({type: 'user_message', content: 'hello'})));
  return {client, finished};
}

/** The session id the client's `connected` frame announces, read after the fact; attach it before any frame arrives. */
export function announcedId(client: WebSocket): () => string {
  let sessionId = '';
  client.on('message', raw => {
    const frame = JSON.parse(String(raw)) as {type: string; sessionId?: string};
    if (frame.type === 'connected') sessionId = frame.sessionId ?? '';
  });
  return () => sessionId;
}

/** Tears every socket and server down, so a red test reports instead of hanging the run. */
export async function stopEngines(): Promise<void> {
  for (const client of clients.splice(0)) client.terminate();
  for (const hal of servers.splice(0)) await hal.stop();
}

/** The one session a store holds, for asserting what survived a close. */
export async function onlySession(store: SessionStore, sessionId: string): Promise<ChatSession | undefined> {
  return (await store.get(sessionId)) as ChatSession | undefined;
}
